def _dedupe_by_key(items, key_func):
    result = []
    seen = set()
    for item in items:
        key = key_func(item)
        if key in seen:
            continue
        seen.add(key)
        result.append(item)
    return result


def noticias_efetivas_ticker(ticker):
    if not isinstance(ticker, dict):
        return []
    mode = str(ticker.get("source_mode") or "portal_manual")
    manual = ticker.get("news", []) if isinstance(ticker.get("news"), list) else []
    cache = ticker.get("portal_cache") if isinstance(ticker.get("portal_cache"), dict) else {}
    portal = cache.get("news", []) if isinstance(cache.get("news"), list) else []
    if mode == "manual":
        source = manual
    elif mode == "portal":
        source = portal
    else:
        source = list(portal) + list(manual)
    return _dedupe_by_key(source, lambda x: (str(x.get("url") or "").strip().lower() or str(x.get("titulo") or "").strip().lower()))


def agenda_efetiva_ticker(ticker):
    if not isinstance(ticker, dict):
        return []
    mode = str(ticker.get("source_mode") or "portal_manual")
    manual = ticker.get("agenda", []) if isinstance(ticker.get("agenda"), list) else []
    cache = ticker.get("portal_cache") if isinstance(ticker.get("portal_cache"), dict) else {}
    portal = cache.get("agenda", []) if isinstance(cache.get("agenda"), list) else []
    if mode == "manual":
        source = manual
    elif mode == "portal":
        source = portal
    else:
        source = list(portal) + list(manual)
    return _dedupe_by_key(
        source,
        lambda x: (
            str(x.get("id") or "").strip().lower()
            or "|".join([
                str(x.get("data") or ""), str(x.get("hora") or ""),
                str(x.get("titulo") or "").strip().lower(), str(x.get("entidade") or "").strip().lower()
            ])
        ),
    )


def noticias_ativas_ticker(ticker, dia=None):
    if not isinstance(ticker, dict) or not ticker.get("enabled", True):
        return []
    dia = dia or datetime.now().date()
    ativos = []
    for item in noticias_efetivas_ticker(ticker):
        if not item.get("ativo", True):
            continue
        inicio = _data_from_iso(item.get("inicio"), dia)
        fim = _data_from_iso(item.get("fim"), None) if item.get("fim") else None
        if dia < inicio:
            continue
        if fim and dia > fim:
            continue
        if not (str(item.get("titulo") or "").strip() or str(item.get("mensagem") or "").strip()):
            continue
        ativos.append(item)
    return ativos


def agenda_ativa_ticker(ticker, dia=None):
    if not isinstance(ticker, dict) or not ticker.get("enabled", True) or not ticker.get("agenda_enabled", True):
        return []
    dia = dia or datetime.now().date()
    ativos = []
    for item in agenda_efetiva_ticker(ticker):
        if not item.get("ativo", True) or str(item.get("status") or "agendado") != "agendado":
            continue
        data_item = _data_from_iso(item.get("data"), dia)
        if data_item < dia:
            continue
        if not any(str(item.get(k) or "").strip() for k in ("titulo", "sistema", "entidade", "responsavel", "local")):
            continue
        ativos.append(item)
    return sorted(ativos, key=lambda x: (str(x.get("data") or ""), str(x.get("hora") or ""), str(x.get("titulo") or "")))


class _PortalNode:
    __slots__ = ("tag", "attrs", "children", "parts", "parent")
    def __init__(self, tag="root", attrs=None, parent=None):
        self.tag = tag
        self.attrs = dict(attrs or [])
        self.children = []
        self.parts = []
        self.parent = parent

    def classes(self):
        return set(str(self.attrs.get("class") or "").split())

    def text(self):
        chunks = []
        chunks.extend(self.parts)
        for child in self.children:
            chunks.append(child.text())
        return " ".join(" ".join(chunks).split())

    def find_all(self, tag=None, classes=None):
        wanted = set(classes or [])
        out = []
        for child in self.children:
            if (tag is None or child.tag == tag) and (not wanted or wanted.issubset(child.classes())):
                out.append(child)
            out.extend(child.find_all(tag=tag, classes=wanted))
        return out

    def find_first(self, tag=None, classes=None):
        values = self.find_all(tag=tag, classes=classes)
        return values[0] if values else None


class _PortalHTMLParser(HTMLParser):
    VOID_TAGS = {"area","base","br","col","embed","hr","img","input","link","meta","param","source","track","wbr"}
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = _PortalNode()
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        node = _PortalNode(tag, attrs, self.stack[-1])
        self.stack[-1].children.append(node)
        if tag not in self.VOID_TAGS:
            self.stack.append(node)

    def handle_startendtag(self, tag, attrs):
        node = _PortalNode(tag, attrs, self.stack[-1])
        self.stack[-1].children.append(node)

    def handle_endtag(self, tag):
        for i in range(len(self.stack)-1, 0, -1):
            if self.stack[i].tag == tag:
                self.stack = self.stack[:i]
                return

    def handle_data(self, data):
        if data and data.strip():
            self.stack[-1].parts.append(data.strip())


def _portal_parse_tree(markup):
    parser = _PortalHTMLParser()
    parser.feed(markup or "")
    parser.close()
    return parser.root


def _portal_text(node):
    return node.text().strip() if node is not None else ""


def _portal_find_input_value(root, name):
    for node in root.find_all(tag="input"):
        if str(node.attrs.get("name") or "") == name:
            return str(node.attrs.get("value") or "")
    return ""


def _portal_credentials():
    try:
        section = st.secrets.get("portal_ss", {})
        email = str(section.get("email") or section.get("usuario") or "").strip()
        senha = str(section.get("senha") or section.get("password") or "")
        return email, senha
    except Exception:
        return "", ""


def _portal_open_text(opener, url, data=None, referer=None, timeout=18):
    headers = {
        "User-Agent": PORTAL_USER_AGENT,
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        "Accept-Language": "pt-BR,pt;q=0.9,en;q=0.6",
    }
    if referer:
        headers["Referer"] = referer
    body = None
    method = "GET"
    if data is not None:
        body = urlencode(data).encode("utf-8")
        headers["Content-Type"] = "application/x-www-form-urlencoded"
        method = "POST"
    req = Request(url, data=body, headers=headers, method=method)
    with opener.open(req, timeout=timeout) as resp:
        raw = resp.read()
        content_type = str(resp.headers.get("Content-Type", ""))
        charset = "utf-8"
        m = re.search(r"charset=([\w.-]+)", content_type, flags=re.I)
        if m:
            charset = m.group(1)
        try:
            text = raw.decode(charset, errors="replace")
        except LookupError:
            text = raw.decode("utf-8", errors="replace")
        return text, resp.geturl(), dict(resp.headers)


def _portal_login(email, senha):
    jar = CookieJar()
    opener = build_opener(HTTPCookieProcessor(jar))
    login_html, _, _ = _portal_open_text(opener, PORTAL_LOGIN_URL)
    root = _portal_parse_tree(login_html)
    csrf = _portal_find_input_value(root, "csrfmiddlewaretoken")
    if not csrf:
        raise RuntimeError("O portal não retornou o token CSRF do formulário de login.")
    post_data = {"csrfmiddlewaretoken": csrf, "email": email, "senha": senha}
    result_html, final_url, _ = _portal_open_text(opener, PORTAL_LOGIN_URL, data=post_data, referer=PORTAL_LOGIN_URL)
    result_root = _portal_parse_tree(result_html)
    still_login = bool(_portal_find_input_value(result_root, "csrfmiddlewaretoken") and result_root.find_first(tag="form", classes={"login-form"}))
    if "/login" in urlparse(final_url).path.lower() or still_login:
        raise RuntimeError("Login no S&S Conecta não foi aceito. Verifique as credenciais em Secrets.")
    return opener


def _portal_badge_category(tipo):
    value = str(tipo or "").strip().lower()
    if "corre" in value:
        return "correcao"
    if "melhoria" in value or "aprimora" in value:
        return "melhoria"
    if "novo" in value or "novidade" in value or "funcional" in value:
        return "novo"
    if "importante" in value or "crít" in value or "critic" in value:
        return "importante"
    return "aviso"


def _portal_parse_updates(markup):
    root = _portal_parse_tree(markup)
    items = []
    known_types = ["Correção", "Melhoria", "Novo", "Novidade", "Nova funcionalidade", "Atualização", "Aviso", "Importante"]
    for card in root.find_all(tag="div", classes={"aviso-card"}):
        title = _portal_text(card.find_first(tag="h4"))
        if not title:
            continue
        resumo = _portal_text(card.find_first(tag="p", classes={"aviso-resumo"}))
        badges = card.find_all(tag="span", classes={"badge"})
        badge_texts = [_portal_text(b) for b in badges]
        tipo = next((b for b in badge_texts if any(k.lower() in b.lower() for k in known_types)), "Atualização")
        modulo = "Geral"
        for badge in badges:
            if badge.find_first(tag="i", classes={"bi-grid"}) is not None:
                modulo = _portal_text(badge) or "Geral"
                break
        full_text = card.text()
        versao_m = re.search(r"Vers[aã]o\s+([0-9A-Za-z._-]+)", full_text, flags=re.I)
        versao = versao_m.group(1) if versao_m else ""
        pub_m = re.search(r"Publicado\s+em\s+(\d{2}/\d{2}/\d{4})(?:\s+(\d{2}:\d{2}))?", full_text, flags=re.I)
        publicado_em = " ".join([g for g in pub_m.groups() if g]) if pub_m else ""
        inicio = datetime.now().date().isoformat()
        if pub_m:
            try:
                inicio = datetime.strptime(pub_m.group(1), "%d/%m/%Y").date().isoformat()
            except Exception:
                pass
        href = ""
        for a in card.find_all(tag="a"):
            candidate = str(a.attrs.get("href") or "")
            if "/atualizacoes/" in candidate:
                href = urljoin(PORTAL_BASE_URL, candidate)
                break
        item_id = ""
        id_m = re.search(r"/atualizacoes/(\d+)/?", href)
        if id_m:
            item_id = id_m.group(1)
        items.append({
            "id": f"portal_news_{item_id or hashlib.sha1((title+href).encode('utf-8')).hexdigest()[:12]}",
            "sistema": modulo,
            "categoria": _portal_badge_category(tipo),
            "titulo": title,
            "mensagem": resumo,
            "url": href,
            "inicio": inicio,
            "fim": "",
            "ativo": True,
            "origem": "portal",
            "versao": versao,
            "publicado_em": publicado_em,
        })
    return items


def _portal_parse_agenda(markup, data_ref):
    root = _portal_parse_tree(markup)
    items = []
    for card in root.find_all(tag="div", classes={"agenda-item"}):
        time_node = card.find_first(tag="div", classes={"agenda-time"})
        strong_time = time_node.find_first(tag="strong") if time_node else None
        hora = _portal_text(strong_time)[:5] or "08:00"
        title = _portal_text(card.find_first(tag="h4")) or "Compromisso"
        status_area = card.find_first(tag="div", classes={"agenda-status-area"})
        status_texts = [_portal_text(n) for n in status_area.find_all(tag="span")] if status_area else []
        status = "agendado"
        for txt in status_texts:
            low = txt.lower()
            if "realizado" in low:
                status = "realizado"; break
            if "cancelado" in low:
                status = "cancelado"; break
            if "agendado" in low:
                status = "agendado"
        modalidade = "outro"
        for txt in status_texts:
            low = txt.lower()
            if "presencial" in low:
                modalidade = "presencial"; break
            if "online" in low or "remoto" in low:
                modalidade = "online"; break
            if "híbr" in low or "hibr" in low:
                modalidade = "hibrido"; break
        details = {}
        for detail in card.find_all(tag="div", classes={"agenda-detail"}):
            label = _portal_text(detail.find_first(tag="span")).strip().lower()
            value = _portal_text(detail.find_first(tag="strong")).strip()
            if label:
                details[label] = value
        agenda_id = ""
        for a in card.find_all(tag="a"):
            candidate = str(a.attrs.get("href") or "")
            m = re.search(r"/agenda/(\d+)/", candidate)
            if m:
                agenda_id = m.group(1)
                break
            m = re.search(r"agenda_id=(\d+)", candidate)
            if m:
                agenda_id = m.group(1)
                break
        day_url = f"{PORTAL_AGENDA_URL}?data={data_ref.isoformat()}"
        items.append({
            "id": f"portal_agenda_{agenda_id or hashlib.sha1((data_ref.isoformat()+hora+title+details.get('entidade','')).encode('utf-8')).hexdigest()[:12]}",
            "titulo": title,
            "data": data_ref.isoformat(),
            "hora": hora,
            "sistema": details.get("sistema", ""),
            "entidade": details.get("entidade", ""),
            "responsavel": details.get("responsável", details.get("responsavel", "")),
            "local": details.get("local", ""),
            "modalidade": modalidade,
            "status": status,
            "url": day_url,
            "ativo": True,
            "origem": "portal",
        })
    return items


def _portal_sync_data(email, senha, agenda_days=7):
    opener = _portal_login(email, senha)
    updates_html, updates_final, _ = _portal_open_text(opener, PORTAL_UPDATES_URL, referer=PORTAL_BASE_URL + "/")
    if "/login" in urlparse(updates_final).path.lower():
        raise RuntimeError("A sessão do portal expirou durante a leitura de Atualizações.")
    news = _portal_parse_updates(updates_html)
    agenda = []
    today = datetime.now().date()
    for offset in range(max(0, int(agenda_days)) + 1):
        day = today + timedelta(days=offset)
        url = f"{PORTAL_AGENDA_URL}?data={day.isoformat()}"
        agenda_html, agenda_final, _ = _portal_open_text(opener, url, referer=PORTAL_AGENDA_URL)
        if "/login" in urlparse(agenda_final).path.lower():
            raise RuntimeError("A sessão do portal expirou durante a leitura da Agenda.")
        agenda.extend(_portal_parse_agenda(agenda_html, day))
    agenda = _dedupe_by_key(agenda, lambda x: str(x.get("id") or ""))
    return news, agenda


def _portal_last_sync_dt(ticker):
    cache = ticker.get("portal_cache") if isinstance(ticker.get("portal_cache"), dict) else {}
    raw = str(cache.get("last_sync") or "")
    if not raw:
        return None
    try:
        return datetime.fromisoformat(raw)
    except Exception:
        return None


def sincronizar_portal_ticker(ticker, force=False):
    if not isinstance(ticker, dict) or not ticker.get("portal_enabled", True):
        return False, "disabled"
    mode = str(ticker.get("source_mode") or "portal_manual")
    if mode == "manual":
        return False, "manual"
    email, senha = _portal_credentials()
    cache = ticker.setdefault("portal_cache", {"news": [], "agenda": [], "last_sync": "", "last_status": "never", "last_error": ""})
    if not email or not senha:
        cache["last_status"] = "not_configured"
        cache["last_error"] = "Credenciais ausentes em st.secrets[portal_ss]."
        return False, "not_configured"
    last_dt = _portal_last_sync_dt(ticker)
    interval = max(1, min(60, int(ticker.get("portal_interval_minutes", 5))))
    if not force and last_dt and (datetime.now() - last_dt).total_seconds() < interval * 60:
        return False, "fresh"
    try:
        news, agenda = _portal_sync_data(email, senha, int(ticker.get("portal_agenda_days", 7)))
        cache["news"] = news
        cache["agenda"] = agenda
        cache["last_sync"] = datetime.now().isoformat(timespec="seconds")
        cache["last_status"] = "ok"
        cache["last_error"] = ""
        return True, "ok"
    except Exception as exc:
        cache["last_status"] = "error"
        cache["last_error"] = str(exc)[:500]
        return False, "error"


