def config_hash(data):
    raw = json.dumps(data, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def url_valida(url):
    try:
        parsed = urlparse(str(url).strip())
        return parsed.scheme in ("http", "https") and bool(parsed.netloc)
    except Exception:
        return False


def _mascot_alert_data_uri():
    # Preferimos a versão embutida para que o mascote não dependa de arquivos
    # externos no deploy. O arquivo em assets continua aceito como fallback.
    if MASCOT_ALERT_EMBEDDED_B64:
        return f"data:image/png;base64,{MASCOT_ALERT_EMBEDDED_B64}"
    try:
        if MASCOT_ALERT_PATH.exists():
            raw = base64.b64encode(MASCOT_ALERT_PATH.read_bytes()).decode("ascii")
            return f"data:image/png;base64,{raw}"
    except Exception:
        pass
    return ""


def _mascot_sim_data_uri():
    if MASCOT_SIM_EMBEDDED_B64:
        return f"data:image/png;base64,{MASCOT_SIM_EMBEDDED_B64}"
    return ""


def _iframe_policy_from_headers(headers, final_url=""):
    xfo = str(headers.get("X-Frame-Options", "") or "").strip()
    csp = str(headers.get("Content-Security-Policy", "") or "").strip()
    reasons = []

    if xfo:
        xfo_low = xfo.lower()
        if "deny" in xfo_low:
            reasons.append("X-Frame-Options: DENY")
        elif "sameorigin" in xfo_low:
            reasons.append("X-Frame-Options: SAMEORIGIN")
        elif "allow-from" in xfo_low and APP_EMBED_ORIGIN.lower() not in xfo_low:
            reasons.append(f"X-Frame-Options: {xfo}")

    if csp:
        directives = [d.strip() for d in csp.split(";") if d.strip()]
        frame_ancestors = next((d for d in directives if d.lower().startswith("frame-ancestors")), "")
        if frame_ancestors:
            sources = frame_ancestors.split()[1:]
            sources_low = [src.lower() for src in sources]
            app_origin = APP_EMBED_ORIGIN.lower()
            allowed = (
                "*" in sources_low
                or app_origin in sources_low
                or any(src.endswith("streamlit.app") and app_origin.endswith(src.lstrip("*.")) for src in sources_low if src.startswith("*."))
            )
            if "'none'" in sources_low or (not allowed and sources_low):
                reasons.append(f"CSP: {frame_ancestors}")

    return {
        "blocked": bool(reasons),
        "status": "blocked" if reasons else "allowed",
        "reason": " · ".join(reasons) if reasons else "Nenhum bloqueio de iframe identificado nos cabeçalhos.",
        "x_frame_options": xfo,
        "content_security_policy": csp,
        "final_url": final_url,
    }


@st.cache_data(ttl=300, show_spinner=False)
def detectar_bloqueio_iframe(url):
    """Verificação preventiva. Só marca como bloqueado quando os cabeçalhos confirmam a restrição."""
    url = str(url or "").strip()
    if not url_valida(url):
        return {"blocked": False, "status": "unknown", "reason": "URL inválida ou incompleta.", "final_url": url}

    headers = {
        "User-Agent": "Mozilla/5.0 (compatible; S&S-Monitor/2.7; +https://monitoramentog4.streamlit.app)",
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        "Accept-Language": "pt-BR,pt;q=0.9,en;q=0.6",
    }

    # HEAD primeiro; alguns servidores não aceitam HEAD, então fazemos GET mínimo como fallback.
    attempts = [("HEAD", None), ("GET", "bytes=0-1024")]
    last_error = ""
    for method, range_header in attempts:
        req_headers = dict(headers)
        if range_header:
            req_headers["Range"] = range_header
        req = Request(url, headers=req_headers, method=method)
        try:
            with urlopen(req, timeout=5, context=ssl.create_default_context()) as resp:
                result = _iframe_policy_from_headers(resp.headers, getattr(resp, "url", url))
                result["http_status"] = getattr(resp, "status", None)
                return result
        except HTTPError as exc:
            # Mesmo um 401/403 costuma trazer os cabeçalhos de segurança que precisamos analisar.
            result = _iframe_policy_from_headers(exc.headers or {}, getattr(exc, "url", url))
            result["http_status"] = getattr(exc, "code", None)
            if result.get("blocked"):
                return result
            last_error = f"HTTP {getattr(exc, 'code', '')}".strip()
            if method == "GET":
                result.update({"status": "unknown", "reason": f"Não foi possível confirmar a compatibilidade ({last_error})."})
                return result
        except (URLError, TimeoutError, ssl.SSLError, OSError) as exc:
            last_error = str(getattr(exc, "reason", exc))
            continue
        except Exception as exc:
            last_error = str(exc)
            continue

    return {
        "blocked": False,
        "status": "unknown",
        "reason": f"Não foi possível verificar os cabeçalhos do site: {last_error or 'sem resposta' }.",
        "final_url": url,
    }


def verificar_paineis_iframe(paineis):
    """Executa os testes automáticos em paralelo para não atrasar o início da apresentação."""
    resultados = {}
    automaticos = [p for p in paineis if p.get("iframe_mode", "auto") == "auto" and url_valida(p.get("link", ""))]
    if automaticos:
        workers = min(6, max(1, len(automaticos)))
        with ThreadPoolExecutor(max_workers=workers) as executor:
            futures = {executor.submit(detectar_bloqueio_iframe, p.get("link", "")): p.get("id") for p in automaticos}
            for future in as_completed(futures):
                pid = futures[future]
                try:
                    resultados[pid] = future.result()
                except Exception as exc:
                    resultados[pid] = {"blocked": False, "status": "unknown", "reason": f"Falha na verificação: {exc}"}

    for p in paineis:
        mode = p.get("iframe_mode", "auto")
        if mode == "fallback":
            resultados[p.get("id")] = {
                "blocked": True,
                "status": "manual",
                "reason": "Painel configurado para usar o aviso personalizado em vez do iframe.",
                "final_url": p.get("link", ""),
            }
        elif mode == "force_iframe":
            resultados[p.get("id")] = {
                "blocked": False,
                "status": "forced",
                "reason": "Abertura em iframe forçada pela configuração do painel.",
                "final_url": p.get("link", ""),
            }
        else:
            resultados.setdefault(p.get("id"), {"blocked": False, "status": "unknown", "reason": "Compatibilidade não confirmada."})
    return resultados


def _clamp_int(value, default, minimum, maximum):
    try:
        return max(minimum, min(maximum, int(value)))
    except Exception:
        return default


def migrar_config_legada(data):
    """Migra configuração 2.0/2.1 (perfis por nome) para o formato 2.3 (perfis por ID)."""
    if not isinstance(data, dict):
        return copy.deepcopy(DEFAULT_CONFIG)

    profiles = data.get("profiles")
    if not isinstance(profiles, dict) or not profiles:
        return copy.deepcopy(DEFAULT_CONFIG)

    # Já está no formato atual se as entradas tiverem id/nome.
    if all(isinstance(v, dict) and v.get("id") and v.get("nome") for v in profiles.values()):
        return data

    old_active = data.get("active_profile")
    new_profiles = {}
    name_to_id = {}

    for old_name, old_profile in profiles.items():
        if not isinstance(old_profile, dict):
            continue
        pid = novo_id("pr_")
        name_to_id[str(old_name)] = pid
        old_sim_seconds = _clamp_int(old_profile.get("sim_refresh_seconds", 20), 20, 0, 300)
        new_panels = []
        for p in old_profile.get("paineis", []):
            if not isinstance(p, dict):
                continue
            nome = str(p.get("nome") or "Novo Painel")
            link = str(p.get("link") or "")
            old_reload = bool(p.get("recarregar", True))
            is_sim = "sim" in nome.lower() or "sim-submissions" in link.lower()
            new_panels.append(
                {
                    "id": str(p.get("id") or novo_id("p_")),
                    "nome": nome,
                    "link": link,
                    "tempo": _clamp_int(p.get("tempo", 20), 20, 5, 600),
                    "ativo": bool(p.get("ativo", True)),
                    "reload_enabled": old_reload,
                    "reload_strategy": "interval" if is_sim and old_sim_seconds > 0 else "on_show",
                    "reload_interval": old_sim_seconds if is_sim and old_sim_seconds > 0 else 60,
                    "preserve_session": not old_reload,
                    "tipo": "sim" if is_sim else "normal",
                }
            )

        new_profiles[pid] = {
            "id": pid,
            "nome": str(old_name),
            "paineis": new_panels,
            "horas_reload_geral": _clamp_int(old_profile.get("horas_reload_geral", 0), 0, 0, 24),
            "auto_ocultar_controles": bool(old_profile.get("auto_ocultar_controles", True)),
            "modo_tv_padrao": bool(old_profile.get("modo_tv_padrao", False)),
            "preload_seconds": 8,
            "watchdog_seconds": 90,
            "ui_scale": 100,
            "toolbar_position": "top",
            "transition_ms": 220,
            "show_clock": True,
            "show_dots": True,
            "show_status": True,
            "config_view": "compact",
        }

    if not new_profiles:
        return copy.deepcopy(DEFAULT_CONFIG)

    default_id = name_to_id.get(str(old_active)) or next(iter(new_profiles))
    return {"version": CONFIG_VERSION, "default_profile_id": default_id, "profiles": new_profiles, "ticker": normalizar_ticker(data.get("ticker")), "sim_alerts": normalizar_sim_alerts(data.get("sim_alerts"))}


def normalizar_config(data):
    data = migrar_config_legada(copy.deepcopy(data))
    if not isinstance(data, dict):
        return copy.deepcopy(DEFAULT_CONFIG)

    profiles = data.get("profiles")
    if not isinstance(profiles, dict) or not profiles:
        return copy.deepcopy(DEFAULT_CONFIG)

    normalized_profiles = {}
    seen_profile_ids = set()
    for key, profile in profiles.items():
        if not isinstance(profile, dict):
            continue
        pid = str(profile.get("id") or key or novo_id("pr_"))
        if pid in seen_profile_ids:
            pid = novo_id("pr_")
        seen_profile_ids.add(pid)

        nome = str(profile.get("nome") or "Perfil")
        raw_panels = profile.get("paineis") if isinstance(profile.get("paineis"), list) else []
        panels = []
        seen_panel_ids = set()
        for p in raw_panels:
            if not isinstance(p, dict):
                continue
            panel_id = str(p.get("id") or novo_id("p_"))
            if panel_id in seen_panel_ids:
                panel_id = novo_id("p_")
            seen_panel_ids.add(panel_id)

            legacy_reload = p.get("recarregar")
            reload_enabled = bool(p.get("reload_enabled", legacy_reload if legacy_reload is not None else True))
            strategy = str(p.get("reload_strategy") or "on_show")
            if strategy not in {"on_show", "interval"}:
                strategy = "on_show"
            panel_type = str(p.get("tipo") or "normal")
            if panel_type not in {"normal", "sim", "personalizado"}:
                panel_type = "normal"

            tempo_normalizado = _clamp_int(p.get("tempo", 20), 20, 5, 600)
            max_focus_seconds = max(1, tempo_normalizado - 1)
            default_focus_seconds = min(20, max_focus_seconds)
            focus_preset = str(p.get("focus_preset") or ("sim_right" if panel_type == "sim" else "custom"))
            if focus_preset not in {"custom", "sim_right", "right", "center", "left", "top_right", "bottom_right"}:
                focus_preset = "custom"

            panels.append(
                {
                    "id": panel_id,
                    "nome": str(p.get("nome") or "Novo Painel"),
                    "link": str(p.get("link") or ""),
                    "tempo": tempo_normalizado,
                    "ativo": bool(p.get("ativo", True)),
                    "reload_enabled": reload_enabled,
                    "reload_strategy": strategy,
                    "reload_interval": _clamp_int(p.get("reload_interval", 60), 60, 5, 3600),
                    "preserve_session": bool(p.get("preserve_session", not reload_enabled)),
                    "tipo": panel_type,
                    "focus_enabled": bool(p.get("focus_enabled", panel_type == "sim")),
                    "focus_seconds": _clamp_int(p.get("focus_seconds", default_focus_seconds), default_focus_seconds, 1, max_focus_seconds),
                    "focus_zoom": _clamp_int(p.get("focus_zoom", 175), 175, 100, 300),
                    "focus_x": _clamp_int(p.get("focus_x", 87 if panel_type == "sim" else 50), 87 if panel_type == "sim" else 50, 0, 100),
                    "focus_y": _clamp_int(p.get("focus_y", 52 if panel_type == "sim" else 50), 52 if panel_type == "sim" else 50, 0, 100),
                    "focus_transition_ms": _clamp_int(p.get("focus_transition_ms", 600), 600, 0, 2000),
                    "focus_preset": focus_preset,
                    "iframe_mode": str(p.get("iframe_mode", "auto")) if str(p.get("iframe_mode", "auto")) in {"auto", "force_iframe", "fallback"} else "auto",
                }
            )

        profile_norm = {
            "id": pid,
            "nome": nome,
            "paineis": panels,
            "horas_reload_geral": _clamp_int(profile.get("horas_reload_geral", 0), 0, 0, 24),
            "auto_ocultar_controles": bool(profile.get("auto_ocultar_controles", True)),
            "modo_tv_padrao": bool(profile.get("modo_tv_padrao", False)),
            "preload_seconds": _clamp_int(profile.get("preload_seconds", 8), 8, 0, 30),
            "watchdog_seconds": _clamp_int(profile.get("watchdog_seconds", 90), 90, 30, 600),
            "ui_scale": int(profile.get("ui_scale", 100)) if int(profile.get("ui_scale", 100)) in {90, 100, 110, 125} else 100,
            "toolbar_position": str(profile.get("toolbar_position", "top")) if str(profile.get("toolbar_position", "top")) in {"top", "bottom"} else "top",
            "transition_ms": int(profile.get("transition_ms", 220)) if int(profile.get("transition_ms", 220)) in {0, 150, 220, 400} else 220,
            "show_clock": bool(profile.get("show_clock", True)),
            "show_dots": bool(profile.get("show_dots", True)),
            "show_status": bool(profile.get("show_status", True)),
            "config_view": str(profile.get("config_view", "compact")) if str(profile.get("config_view", "compact")) in {"compact", "detailed"} else "compact",
        }
        normalized_profiles[pid] = profile_norm

    if not normalized_profiles:
        return copy.deepcopy(DEFAULT_CONFIG)

    default_id = str(data.get("default_profile_id") or "")
    if default_id not in normalized_profiles:
        default_id = next(iter(normalized_profiles))

    ticker = normalizar_ticker(data.get("ticker"))
    sim_alerts = normalizar_sim_alerts(data.get("sim_alerts"))
    return {"version": CONFIG_VERSION, "default_profile_id": default_id, "profiles": normalized_profiles, "ticker": ticker, "sim_alerts": sim_alerts}


def validar_config_importada(data):
    erros = []
    avisos = []
    if not isinstance(data, dict):
        return ["O arquivo precisa conter um objeto JSON."], avisos
    profiles = data.get("profiles")
    if not isinstance(profiles, dict) or not profiles:
        erros.append("Nenhum perfil de monitoramento foi encontrado.")
        return erros, avisos

    nomes = set()
    total_panels = 0
    for key, profile in profiles.items():
        if not isinstance(profile, dict):
            erros.append(f"Perfil {key} possui formato inválido.")
            continue
        nome = str(profile.get("nome") or key).strip()
        if nome.lower() in nomes:
            avisos.append(f"Há perfis com nome repetido: {nome}.")
        nomes.add(nome.lower())
        paineis = profile.get("paineis", [])
        if not isinstance(paineis, list):
            erros.append(f"Painéis do perfil {nome} não estão em uma lista.")
            continue
        total_panels += len(paineis)
        for p in paineis:
            if not isinstance(p, dict):
                erros.append(f"Há painel inválido no perfil {nome}.")
                continue
            link = str(p.get("link") or "").strip()
            if link and not url_valida(link):
                avisos.append(f"URL aparentemente inválida em {nome}: {link[:60]}")
    if total_panels == 0:
        avisos.append("A configuração importada não possui painéis cadastrados.")

    ticker = data.get("ticker")
    if isinstance(ticker, dict):
        news = ticker.get("news") if isinstance(ticker.get("news"), list) else []
        for item in news:
            if not isinstance(item, dict):
                continue
            link = str(item.get("url") or "").strip()
            if link and not url_valida(link):
                avisos.append(f"Link de notícia aparentemente inválido: {link[:60]}")
    return erros, avisos


def carregar_config():
    if CONFIG_PATH.exists():
        try:
            with CONFIG_PATH.open("r", encoding="utf-8") as f:
                return normalizar_config(json.load(f))
        except Exception as exc:
            try:
                stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
                corrupt = CONFIG_PATH.with_name(f"monitoramento_config.corrompido_{stamp}.json")
                shutil.copy2(CONFIG_PATH, corrupt)
                st.session_state["config_corrompida_backup"] = corrupt.name
            except Exception:
                pass
            st.session_state["ultimo_erro_persistencia"] = f"Falha ao ler configuração: {exc}"
    return copy.deepcopy(DEFAULT_CONFIG)


def salvar_config(config, force=False):
    """Grava apenas quando necessário, com backup e substituição atômica."""
    try:
        cfg = normalizar_config(config)
        current_hash = config_hash(cfg)
        if not force and st.session_state.get("ultimo_hash_salvo") == current_hash:
            return True

        if CONFIG_PATH.exists():
            try:
                current_disk = CONFIG_PATH.read_text(encoding="utf-8")
                disk_hash = hashlib.sha256(current_disk.encode("utf-8")).hexdigest()
                new_raw = json.dumps(cfg, ensure_ascii=False, indent=2)
                new_hash_raw = hashlib.sha256(new_raw.encode("utf-8")).hexdigest()
                if disk_hash != new_hash_raw:
                    shutil.copy2(CONFIG_PATH, BACKUP_PATH)
            except Exception:
                pass

        raw = json.dumps(cfg, ensure_ascii=False, indent=2)
        fd, temp_name = tempfile.mkstemp(prefix="monitoramento_", suffix=".json", dir=str(CONFIG_PATH.parent))
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as tmp:
                tmp.write(raw)
                tmp.flush()
                os.fsync(tmp.fileno())
            os.replace(temp_name, CONFIG_PATH)
        finally:
            if os.path.exists(temp_name):
                os.unlink(temp_name)

        st.session_state["ultimo_hash_salvo"] = current_hash
        st.session_state["ultima_gravacao"] = datetime.now().strftime("%H:%M:%S")
        st.session_state.pop("ultimo_erro_persistencia", None)
        return True
    except Exception as exc:
        st.session_state["ultimo_erro_persistencia"] = str(exc)
        return False


def regenerar_ids(perfil):
    novo = copy.deepcopy(perfil)
    novo["id"] = novo_id("pr_")
    for p in novo.get("paineis", []):
        p["id"] = novo_id("p_")
    return novo


def perfil_por_id(config, pid):
    return config["profiles"].get(pid)


def perfil_id_da_url(config):
    requested = str(st.query_params.get("perfil", "") or "")
    if requested in config["profiles"]:
        return requested
    return config.get("default_profile_id") if config.get("default_profile_id") in config["profiles"] else next(iter(config["profiles"]))


def perfil_ativos(perfil):
    return [
        p for p in perfil.get("paineis", [])
        if p.get("ativo", True) and p.get("link", "").strip() and url_valida(p.get("link", ""))
    ]


def b64_json(data):
    raw = json.dumps(data, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    return base64.b64encode(raw).decode("ascii")


